"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4389],{8766(e){e.exports=JSON.parse('{"title":"\uc804\uc5ed \uc0c1\ud0dc \uad00\ub9ac\uc640 \uc2dc\uc0ac\ud558\ub294 \ubc14","date":"2024-12-21","coverUrl":"/kudzu-based-bench/assets/notion/bacc3d646e6d35dd.png","html":"<h2 data-notion-block-id=\\"162e548d-8a8e-801a-b46c-cfbfc545e5d0\\" id=\\"162e548d-8a8e-801a-b46c-cfbfc545e5d0\\">\uc804\uc5ed \uc0c1\ud0dc \uad00\ub9ac\uc640 \uc2dc\uc0ac\ud558\ub294 \ubc14</h2><a href=\\"https://www.frontendundefined.com/posts/monthly/react-state-management-reflections/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.frontendundefined.com/posts/monthly/react-state-management-reflections/</a><p data-notion-block-id=\\"162e548d-8a8e-80fe-b67a-c925e9147442\\">\uc800\uc790\uac00 \ub2e4\uc591\ud55c \uc0c1\ud0dc \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc368\ubcf4\uba74\uc11c \ub290\ub080 \uc810\uc744 \ud480\uc5b4\ub0b8 \uae00\uc785\ub2c8\ub2e4. \uc804\uc5ed \uc0c1\ud0dc\ub97c \ub2e4\ub8e8\ub294 \ub85c\uc9c1\uc774 \ud544\uc694\ud55c \ub54c\uac00 \ub9ce\uc774 \uc788\uc9c0\ub9cc, \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc758 \ubaa9\uc801(\ub370\uc774\ud130 \uac00\uc838\uc624\uae30/\uc804\uc5ed\uc5d0\uc11c \uac00\uc838\uc624\uae30)\uacfc \uc800\uc7a5\uc18c\uac00 \ub9ac\uc561\ud2b8 \ubc14\uae65\uc5d0\uc11c \uac00\uc838\uc628\ub2e4\ub294 \uac83\uc744 \uba85\uc2ec\ud574\uc57c \ud560 \uac83\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#aef423ee-c881-4803-a5c7-d940c6246140\\"><code>useEffect</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#aef423ee-c881-4803-a5c7-d940c6246140\\">\uc640 </a><a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#aef423ee-c881-4803-a5c7-d940c6246140\\"><code>useSyncExternalStore</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#aef423ee-c881-4803-a5c7-d940c6246140\\">\uc758 \ucc28\uc774</a>, \uadf8\ub9ac\uace0 \uc0c1\ud0dc \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640\uc758 \uc0c1\ud638\uc791\uc6a9, \uc5ec\ub7ec\uac00\uc9c0\ub97c \uace0\ub824\ud574\uc57c\uaca0\uc8e0. \ub354 \uc790\uc138\ud55c \uc0c1\ud0dc \uad00\ub9ac\uc758 \uc5ed\uc0ac\uc640 \uc790\uc138\ud55c \uc811\uadfc \ubc29\uc2dd\uc740 FrontendMastery\uc758 <a href=\\"https://frontendmastery.com/posts/the-new-wave-of-react-state-management/\\">\ub9ac\uc561\ud2b8 \uc0c1\ud0dc\uad00\ub9ac\uc758 \uc0c8\ub85c\uc6b4 \ubb3c\uacb0</a> \uae00\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"162e548d-8a8e-80c6-8224-f9618dd9926f\\" id=\\"162e548d-8a8e-80c6-8224-f9618dd9926f\\">Next.js\uc5d0\uc11c Astro\ub85c \ubcc0\uacbd\ud558\uae30</h2><a href=\\"https://www.datocms.com/blog/why-we-switched-to-astro\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.datocms.com/blog/why-we-switched-to-astro</a><p data-notion-block-id=\\"162e548d-8a8e-801c-aac2-dd5e02bd0267\\">\uac04\ub2e8\ud558\uac8c Next.js\uc5d0\uc11c \uc2e4\ub9dd\ud55c \uc810\uacfc Astro\ub97c \uc120\ud0dd\ud588\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Next.js\uac00 \uc0ac\uc6a9\uc790\uac00 \ub9ce\uc740\ub9cc\ud07c, \uadf8\uc5d0 \ub530\ub978 \ub2e8\uc810\ub3c4 \uba85\ud655\ud569\ub2c8\ub2e4(<a href=\\"https://www.epicweb.dev/why-i-wont-use-nextjs\\">Why I won\u2019t use next.js</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/d4dabcc7-9269-46bc-a2f2-ed10f9fcf35f#a7149fc6-b56a-405b-be3c-004fdbe51c8b\\">App router\uc758 \uc7a5\ub2e8</a>). \uadf8\ub7f0 \ub9cc\ud07c \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub530\ub77c \uc120\ud0dd\uc9c0\ub97c \ub113\uac8c \ubcf4\ub294 \uac83 \ub610\ud55c \ud544\uc694\ud574\ubcf4\uc785\ub2c8\ub2e4. \uc774 \uae00\uc740 \ub2e8\uc21c\ud788 \uc790\uc2e0\ub4e4\uc758 \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\ucdb0\uc11c \uae00\uc744 \uc37c\uae30\uc5d0, \uc5ec\ub7ec\uac00\uc9c0 \uad00\uc810\uc744 \uc0b4\ud3b4\ubcf4\uae30\ub97c \uc6d0\ud558\uc2e0\ub2e4\uba74 <a href=\\"https://infrequently.org/2024/11/if-not-react-then-what/\\">React\ub97c \uc120\ud0dd\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74</a>\uc744 \uc77d\uae30\ub97c \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. React\ub97c \uc4f0\uc9c0 \ub9d0\uc544\uc57c \ud55c\ub2e4\uc5d0 100% \ub3d9\uc870\ud558\uae34 \uc5b4\ub835\uc9c0\ub9cc(\uadf8\ub9cc\ud07c \uc0dd\ud0dc\uacc4\ub294 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4), React\uc678\uc758 \ub2e4\ub978 \uc120\ud0dd\uc9c0\ub97c \uc120\ud0dd\ud558\ub294 \ub450\ub824\uc6c0\uc744 \uc904\uc5ec\uc57c \ud55c\ub2e4\uace0\ub294 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"162e548d-8a8e-80d4-bb42-c4874b71f3bf\\" id=\\"162e548d-8a8e-80d4-bb42-c4874b71f3bf\\">\ube0c\ub77c\uc6b0\uc800 \uce90\uc2f1\uc758 \uc885\ub958, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ub2e4\ub904\uc57c \ud560\uae4c</h2><a href=\\"https://www.debugbear.com/blog/browser-caching\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/browser-caching</a><p data-notion-block-id=\\"162e548d-8a8e-8056-8d90-dade37465e8d\\">\uce90\uc2f1\uc744 \uc65c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uc9c0, \uce90\uc2dc\uc758 \uc885\ub958, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0 \ubaa8\ub450 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 <code>Cache-Control</code>\ud5e4\ub354\uc640 CDN, \uc11c\ubc84\uc5d0\uc11c \uce90\uc2dc\ub97c \ub2e4\ub8e8\ub294 \ubc29\ubc95\uacfc \uc790\ub8cc\ub97c \uac04\ub2e8\ud558\uac8c\ub9cc \uc18c\uac1c\ud558\uace0 \uc788\uc73c\ub2c8, \uacbd\uc6b0\uc5d0 \ub530\ub77c Next.js\uc758 \uce90\uc2dc \uc704\uce58(<a href=\\"https://nextjs.org/docs/app/building-your-application/caching#overview\\">App router</a>, <a href=\\"https://nextjs.org/docs/pages/building-your-application/data-fetching\\">Page router</a>), <a href=\\"https://tanstack.com/query/latest/docs/framework/react/overview\\">Tanstack query</a>, Vite\uc758 <a href=\\"https://rollupjs.org/configuration-options/#output-assetfilenames\\">hashing\uc73c\ub85c \uce90\uc2dc \ubc84\uc2a4\ud305</a>\u2026 \uc5ec\ub7ec \ubb38\uc11c\ub97c \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"164e548d-8a8e-807b-a6c8-ef1262fcdd25\\" id=\\"164e548d-8a8e-807b-a6c8-ef1262fcdd25\\">Node.js\ub97c \uacc4\uc18d \uc5c5\ub370\uc774\ud2b8 \ud574\uc57c \ud558\ub294 \uc774\uc720</h2><a href=\\"https://nodesource.com/blog/State-of-Nodejs-Performance-2024\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodesource.com/blog/State-of-Nodejs-Performance-2024</a><p data-notion-block-id=\\"164e548d-8a8e-80ee-a735-cc03264b3f13\\">Node.js\uc5d0\uc11c \ubcf4\uc548 \ud328\uce58\ub97c \uc624\ub798 \ud574\uc8fc\uc9c0 \uc54a\ub294 \uc774\uc720 \ub610\ud55c \uc5c5\ub370\uc774\ud2b8\ud574\uc57c \ud558\ub294 \uc774\uc720\uc5d0 \ud3ec\ud568\ub418\uc9c0\ub9cc, \uae30\ubcf8 \ud568\uc218\ub4e4\uc758 \uc131\ub2a5\uc774 \uc62c\ub77c\uac00\ub294 \uac83 \ub610\ud55c \uc8fc\uae30\uc801\uc73c\ub85c \uc5c5\ub370\uc774\ud2b8\ud574\uc57c \ud558\ub294 \uc774\uc720\uc5d0 \ud3ec\ud568\ub429\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc0c1\ub2f9\ud55c \uc131\ub2a5 \uac1c\uc120\uc774 \uc774\ub8e8\uc5b4\uc9c4 API\uc640 \ubca4\uce58\ub9c8\ud06c\ub97c \uc81c\ub300\ub85c \uc2e4\ud589\ud558\uae30 \uc704\ud55c \uac04\ub2e8\ud55c \uc218\uc815\ub3c4 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"164e548d-8a8e-8090-9cc7-d4ef674fb179\\" id=\\"164e548d-8a8e-8090-9cc7-d4ef674fb179\\">CSS \ub2e8\ucd95 \uc18d\uc131\uacfc \uac00\ub3c5\uc131</h2><a href=\\"https://www.havardbrynjulfsen.design/writing/thoughts/my-issues-with-shorthand-properties/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.havardbrynjulfsen.design/writing/thoughts/my-issues-with-shorthand-properties/</a><p data-notion-block-id=\\"164e548d-8a8e-8013-8cec-e81175e48cb6\\">\uac04\ub2e8\ud55c <code>padding</code>, <code>margin</code>\uc5d0\uc11c\ubd80\ud130, \uc5ec\ub7ec \ubc29\uba74\uc5d0\uc11c \ub2e8\ucd95 \uc18d\uc131\uc744 \uc4f0\uc9c0\ub9cc, \ub9ce\uc774 \uc4f0\ub294 \ub2e8\ucd95 \uc18d\uc131\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\uace0, \ub54c\uc5d0 \ub530\ub77c \ub298\uc5ec\uc4f0\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc800\uc790\ub294 CSS\uc5d0\uc11c\ub9cc\uc744 \uc608\ub97c \ub4e4\uc5c8\uc9c0\ub9cc, \ub2e4\ub978 \uc5b8\uc5b4\uc5d0\uc11c\ub3c4 \ub611\uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"162e548d-8a8e-804e-87ec-eb642cec7fb6\\" id=\\"162e548d-8a8e-804e-87ec-eb642cec7fb6\\">React 19\uc758 ref cleanup\uacfc <code>useCallback</code>.</h2><a href=\\"https://tkdodo.eu/blog/ref-callbacks-react-19-and-the-compiler\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/ref-callbacks-react-19-and-the-compiler</a><p data-notion-block-id=\\"162e548d-8a8e-8095-9236-ea012ea28178\\">\uc800\uc790\uc758 \uc804 \uae00\uc778 ref\ub97c \uc0ac\uc6a9\ud574\uc11c <a href=\\"https://tkdodo.eu/blog/avoiding-use-effect-with-callback-refs\\"><code>useEffect</code></a><a href=\\"https://tkdodo.eu/blog/avoiding-use-effect-with-callback-refs\\">\uc0ac\uc6a9\uc744 \ud53c\ud55c \uae00</a>\uc5d0\uc11c \uc798\ubabb\ub41c \ubd80\ubd84\uc744 \uc218\uc815\ud558\uace0, React 19\uc758 \ucd94\uac00\ub41c ref cleanup\uacfc \ucef4\ud30c\uc77c\ub7ec\uc758 <code>useCallback</code>\uc791\ub3d9\uc5d0 \ub9de\uac8c \uc218\uc815\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubb3c\ub860 \ub9c8\uc9c0\ub9c9\uc5d0 \uc18c\uac1c\ud558\ub4ef\uc774, \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\ub294 \uacbd\uc6b0\uc5d0\ub9cc \uc774 \ubc29\uc2dd\uc744 \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"164e548d-8a8e-80f7-a063-dfa4f33dd194\\" id=\\"164e548d-8a8e-80f7-a063-dfa4f33dd194\\">\ubc88\ub4e4\ub7ec \uc5c6\uc774 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \ud65c\uc6a9\ud558\uae30</h2><a href=\\"https://playfulprogramming.com/posts/modern-js-bundleless\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://playfulprogramming.com/posts/modern-js-bundleless</a><p data-notion-block-id=\\"164e548d-8a8e-8075-831a-c94dfd1a6688\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/14ae548d-8a8e-8059-b8c9-cc040779dd9f#150e548d-8a8e-80ee-9918-f2edf837d40c\\">\ube4c\ub4dc \ub3c4\uad6c \uc5c6\uc774 \ub77c\uc774\ube0c\ub7ec\ub9ac \ubd88\ub7ec\uc624\uae30</a>\uacfc \ube44\uc2b7\ud55c \uae00\uc785\ub2c8\ub2e4(HMR\uacfc \ub9b0\ud130\ub97c \ucd94\uac00\ud568). \uc774 \uae00\ub3c4 commonjs \ub300\uc751 \ub54c\ubb38\uc5d0 esbuild \uacfc\uc815\uc744 \ucd94\uac00\ud55c \uac83\uc774 \uc778\uc0c1\uc801\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"164e548d-8a8e-804a-b4b1-db1e457e7628\\" id=\\"164e548d-8a8e-804a-b4b1-db1e457e7628\\">Micro-Frontend\uc640 Next.js \uba40\ud2f0\uc874</h2><a href=\\"https://techhub.iodigital.com/articles/building-scalable-micro-frontends-with-next-js-multi-zones\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://techhub.iodigital.com/articles/building-scalable-micro-frontends-with-next-js-multi-zones</a><p data-notion-block-id=\\"164e548d-8a8e-8015-b393-d68a7548e10f\\">Next.js\uc758 <code>rewrites</code>\uae30\ub2a5\uc73c\ub85c \uac04\ub2e8\ud558\uac8c \ub2e4\ub978 \uc18c\uc2a4\ucf54\ub4dc \uae30\ubc18(\ubb3c\ub860 \ub458 \ub2e4 Next.js)\uc73c\ub85c Micro Frontend\uc744 \uad6c\ud604\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc790\uc138\ud558\uac8c \uc801\uc6a9\ud558\ub294 \ubc29\ubc95\uc740 \uacf5\uc2dd \ubb38\uc11c\uc758 <a href=\\"https://nextjs.org/docs/pages/building-your-application/deploying/multi-zones\\">Multizone deploying</a>\uc774 \ub354 \uc798 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc7a5\ub2e8\uc810\uacfc \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud560\uc9c0\ub294 \uae00\uc5d0\uc11c \uc798 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"164e548d-8a8e-803c-928b-f39fd98bfb05\\" id=\\"164e548d-8a8e-803c-928b-f39fd98bfb05\\">Node.js\uc640 Readable Stream</h2><a href=\\"https://pavel-romanov.com/exploring-the-core-concepts-of-nodejs-readable-streams\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pavel-romanov.com/exploring-the-core-concepts-of-nodejs-readable-streams</a><p data-notion-block-id=\\"164e548d-8a8e-80c5-a731-d1f66d0879e7\\">Readable Stream\uc774 \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ub418\ub294\uc9c0\uc640 \ud575\uc2ec \uac1c\ub150\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p>"}')}}]);